# [[02_dge_analysis/04_deg_analysis.R]]
# Goal: Run DESeq2 differential expression analysis (DGE) and save results.
#
# Pipeline steps:
#   1. Load dds RDS object generated by 02_rna_processing.R
#   2. Run DESeq2 differential expression test
#   3. Shrink log fold changes using apeglm
#   4. Save full DEG table to results/tables/04_{DataType}_DEG.csv
#   5. Filter significant DEGs (|log2FC| >= 1, pvalue < 0.05) and save to results/tables/04_{DataType}_DEG_sig.csv
#   6. Save serialized DESeq2 results as RDS to _data/RData/02_dge_analysis/

suppressPackageStartupMessages({
  library(DESeq2)
  library(dplyr)
  library(readr)
  library(apeglm)
})

# Dynamically resolve project root
get_project_root <- function() {
  curr <- getwd()
  while (curr != "/" && !file.exists(file.path(curr, "run"))) {
    curr <- dirname(curr)
  }
  return(curr)
}
project_root <- get_project_root()

# Directories
rdata_dir <- file.path(project_root, "_data/RData/02_dge_analysis")
tables_dir <- file.path(project_root, "results/tables")
figures_dir <- file.path(project_root, "results/figures")

dir.create(tables_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(figures_dir, recursive = TRUE, showWarnings = FALSE)

# DEG function
run_deg <- function(datatype) {
  message("\n==============================")
  message("Processing DEG for: ", datatype)
  message("==============================")

  dds_file <- file.path(rdata_dir, paste0("02_", datatype, "_dds.rds"))

  if (!file.exists(dds_file)) {
    stop("File not found: ", dds_file)
  }

  dds <- readRDS(dds_file)

  # Check metadata
  if (!"SampleType" %in% colnames(colData(dds))) {
    stop(datatype, ": SampleType column not found in colData(dds)")
  }

  colData(dds)$SampleType <- droplevels(factor(colData(dds)$SampleType))
  groups <- levels(colData(dds)$SampleType)

  if (length(groups) != 2) {
    stop(
      datatype,
      ": expected exactly 2 SampleType groups, found ",
      length(groups),
      " (",
      paste(groups, collapse = ", "),
      ")"
    )
  }

  message("Comparison: ", groups[2], " vs ", groups[1])
  print(table(colData(dds)$SampleType))

  # Run differential expression
  dds <- DESeq(dds)

  res_raw <- results(dds, independentFiltering = FALSE)
  
  # Shrink fold changes using apeglm
  res <- lfcShrink(
    dds,
    coef = 2,
    type = "apeglm"
  )

  res_df <- as.data.frame(res)
  res_df$stat <- res_raw$stat
  res_df$pvalue <- res_raw$pvalue
  res_df$padj <- res_raw$padj
  res_df$gene_name <- rownames(res_df)

  # Save full results to results/tables/ with prefix 04_
  write.csv(
    res_df,
    file.path(tables_dir, paste0("04_", datatype, "_DEG.csv")),
    row.names = FALSE,
    quote = FALSE
  )

  # Significant genes filter (|log2FC| >= 1, pvalue < 0.05)
  sig_df <- res_df %>%
    filter(
      !is.na(pvalue),
      pvalue < 0.05,
      abs(log2FoldChange) >= 1
    )

  # Save significant results to results/tables/ with prefix 04_
  write.csv(
    sig_df,
    file.path(tables_dir, paste0("04_", datatype, "_DEG_sig.csv")),
    row.names = FALSE,
    quote = FALSE
  )

  message("Significant genes found: ", nrow(sig_df))

  # Save serialized results and dds back to RData
  saveRDS(res, file.path(rdata_dir, paste0("04_", datatype, "_res_shrunk.rds")))
  saveRDS(res_raw, file.path(rdata_dir, paste0("04_", datatype, "_res_raw.rds")))
  saveRDS(dds, file.path(rdata_dir, paste0("04_", datatype, "_dds.rds")))

  message("Finished DGE for ", datatype)
}

# Run analyses
run_deg("RNAseq")
run_deg("RIPseq")

message("\n04_deg_analysis.R completed successfully.")
